#include <bits/stdc++.h>
using namespace std;

const long long mod = 998244353;

long long computeFn(long long x, long long y, long long st, int type, vector<map<long long, long long>> &cache) {
    if (cache[type].count(st)) {
        return cache[type][st];
    }
    if (st == 1) {
        return (type == 0) ? x : y;
    }
    if (st % 2 == 1) {
        long long res = (x * computeFn(x, y, st - 1, type, cache) + y * computeFn(x, y, st - 1, (type + 1) % 2, cache)) % mod;
        cache[type][st] = res;
        return res;
    } else {
        long long half = st / 2;
        long long ch = computeFn(x, y, half, 0, cache);
        long long nch = computeFn(x, y, half, 1, cache);
        long long ans;
        if (type == 0) {
            ans = (ch * ch + nch * nch) % mod;
        } else {
            ans = (2 * ch * nch) % mod;
        }
        cache[type][st] = ans;
        return ans;
    }
}

long long computeBin(long long x, long long st) {
    if (st == 0) return 1;
    if (st == 1) return x;
    long long m = st / 2;
    long long res = computeBin(x, m);
    if (st % 2 == 0) {
        return (res * res) % mod;
    } else {
        return ((res * res) % mod * x) % mod;
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
